INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349937, 14715, 'Al Jazeera English', 'en', 'Largest Ukrainian drone attack on Russia, Moscow says 822 drones shot down', 'https://www.aljazeera.com/video/newsfeed/2026/8/16/16-08-sv-ukraine-largest-drone-attack-russia-ua?traffic_source=rss', 'Ukraine launched hundreds of drones across Russia, killing at least six people and striking a Wildberries logistics hub.', '', '2026-08-16T15:35:53+00:00', '2026-08-16T22:02:05.133795'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349959, 14715, 'Deutsche Welle', 'en', 'Ukraine attacks Wildberries, Russia''s biggest online market', 'https://www.dw.com/en/ukraine-attacks-wildberries-russia-s-biggest-online-market/a-78384605?maca=en-rss-en-world-4025-xml-mrss', 'Since mid-July, Ukraine has been targeting warehouses of Russia''s largest online retailer Wildberries almost every day. Ukraine says it''s disrupting front-line shipments. But experts say it''s disrupting Russia''s economy.', '', '2026-08-16T15:45:00+00:00', '2026-08-16T22:02:13.800859'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
