INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349980, 14715, 'France 24', 'en', 'Drone and missile strikes kill 19 in Russia and Ukraine', 'https://www.france24.com/en/europe/20260816-drone-and-missile-strikes-kill-19-in-russia-and-ukraine', 'At least 19 people were killed Sunday in drone and missile strikes in Russia and Ukraine which destroyed a book market in Kyiv while Moscow faced one of the most massive attacks since the start of the war. Ukraine and Russia have been escalating their long-range strikes for months, resulting in a growing number of civilian casualties, more than four years after the start of the Russian invasion.', 'https://s.france24.com/media/display/89ece206-995a-11f1-9e76-005056a90284/w:1024/p:16x9/46db3463b3cb9c79760936ea765719426849a89c.jpg', '2026-08-16T19:12:31+00:00', '2026-08-16T22:02:19.336461'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349986, 14715, 'France 24', 'en', 'Ukraine: Russian strike destroys Kyiv book market', 'https://www.france24.com/en/video/20260816-ukraine-russian-strike-destroys-kyiv-book-market', 'Kyiv was hit by Russian strikes on Sunday, killing at least four people and injuring six, while a popular outdoor book market was destroyed. Vendors rushed to the scene to assess the damage, with some saying they had lost their shops and their livelihoods.', 'https://s.france24.com/media/display/99c52f64-997b-11f1-ad21-005056a97e36/w:1024/p:16x9/EN-20260816-150123-150249-CS.jpg', '2026-08-16T14:40:52+00:00', '2026-08-16T22:02:19.549735'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
