INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (350855, 14715, 'TIME', 'en', 'Ukraine Launches One of the War’s Largest Drone Attacks, Killing 6', 'https://time.com/article/2026/08/16/ukraine-launches-one-of-the-wars-largest-drone-attacks-killing-6', 'Hundreds of drones targeted Moscow and nearby areas, hitting warehouses linked to Russia’s largest online retailer, amid strikes by both sides.', 'https://static.time.com/v3/assets/bltea6093859af6183b/bltded9b66512f0dbea/6a8209b748c70d8232c5a00c/GettyImages-2290199701.jpg?branch=production', '2026-08-16T19:00:17+00:00', '2026-08-16T22:04:54.910936'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
