INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (350979, 14715, 'ABC Australia', 'en', 'Ukraine targets Moscow and Wildberries warehouse in aerial assault', 'https://www.abc.net.au/news/2026-08-17/ukraine-attack-russia-warehouse-drones/107044644', 'Ukraine''s strikes against targets across Russia are some of its largest so far, and come as Russian forces carry out attacks on Ukrainian cities.', 'https://live-production.wcms.abc-cdn.net.au/fda7ad072019bfce049c2f8ad9a87541?impolicy=wcms_crop_resize&cropH=655&cropW=1164&xPos=0&yPos=655&width=862&height=485', '2026-08-16T19:10:08+00:00', '2026-08-16T22:05:16.947608'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
