INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (334863, 14739, 'The Times of India', 'en', 'LS panel sends notice to Rahul over ''unparliamentary'' remarks against Shah', 'https://timesofindia.indiatimes.com/india/lok-sabha-panel-seeks-rahul-gandhis-response-on-privilege-notices-over-remarks-against-amit-shah/articleshow/133248206.cms', 'Rahul Gandhi has been served a Lok Sabha notice regarding privilege complaints raised by BJP MPs Anurag Thakur and Sanjay Jaiswal. The complaints accuse Gandhi of using inappropriate and disrespectful language towards Amit Shah. He is required to submit a response to the Secretariat by August 28, after which the Speaker will assess both the complaints and his reply.', 'https://static.toiimg.com/photo/msid-133248234,imgsize-904915.cms', '2026-08-14T17:10:57+00:00', '2026-08-14T18:09:03.280756'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
