INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (340790, 14740, 'Le Monde', 'en', 'Hamas disarmament deal offers historic opening, but Israel stands in the way', 'https://www.lemonde.fr/en/international/article/2026/08/15/hamas-disarmament-deal-offers-historic-opening-but-israel-stands-in-the-way_6756539_4.html', 'For the first time in its 39-year history, Hamas agreed to put disarmament on the table. The Board of Peace''s roadmap, approved by Donald Trump, calls for a gradual and verified process to move forward in parallel with the withdrawal of Israeli forces. Benjamin Netanyahu has rejected that approach.', 'https://img.lemde.fr/2025/01/30/457/0/5477/2738/644/322/60/0/bde66b6_ftp-import-images-1-l4n86s6e8cth-5890773-01-06.jpg', '2026-08-15T12:49:47+00:00', '2026-08-16T00:08:06.400314'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
