INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349121, 14740, 'The Times of India', 'en', 'Gaza peace plan: 8 nations condemn Israel''s rejection of US roadmap', 'https://timesofindia.indiatimes.com/world/middle-east/gaza-peace-plan-8-nations-condemn-israels-rejection-of-us-roadmap/articleshow/133278506.cms', 'Several nations condemned Israel''s rejection of the Gaza peace process proposal. This move seriously undermines collective efforts to achieve lasting peace and stability. The roadmap, accepted by Palestinian factions, was a culmination of intensive mediation efforts. Israel insists Hamas must be disarmed before any troop withdrawal occurs. The countries urged the US to compel Israel to fully comply with the plan.', 'https://static.toiimg.com/photo/msid-133278508,imgsize-81348.cms', '2026-08-16T16:15:01+00:00', '2026-08-16T21:58:50.050582'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349143, 14740, 'Mint', 'en', 'Gaza ceasefire talks: US push for peace gains momentum as Jared Kushner meets Hamas chief ahead of Netanyahu meeting', 'https://www.livemint.com/news/us-news/gaza-ceasefire-talks-jared-kushner-meets-hamas-chief-ahead-of-crucial-netanyahu-meeting-11786914157802.html', 'The meeting came days after Israeli Prime Minister Benjamin Netanyahu rejected a 15-point, US-backed roadmap aimed at advancing a ceasefire, Hamas disarmament and an Israeli military withdrawal from Gaza.', 'https://www.livemint.com/lm-img/img/2026/08/16/1600x900/logo/Israel-Palestinians-Gaza-0_1786914224973_1786914271800_420f4f15-edac-4448-a1dd-2e808a7a472c.jpg', '2026-08-16T21:20:11+00:00', '2026-08-16T21:59:00.668635'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
