INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (351874, 14740, 'South China Morning Post', 'en', 'US envoy Kushner visits Hamas leader in push for Gaza road map before Netanyahu meeting', 'https://www.scmp.com/news/world/middle-east/article/3364218/us-envoy-kushner-visits-hamas-leader-push-gaza-road-map-netanyahu-meeting', 'US negotiator and President Donald Trump’s son-in-law Jared Kushner held a rare meeting with the Hamas chief on Sunday in a new diplomatic effort to make progress in the stalled Gaza ceasefire. Kushner will meet Israel’s prime minister on Monday. The talks aim to salvage the new 15-point, US-backed road map for Hamas to disarm in Gaza and Israel to withdraw from the Palestinian territory shattered by war. At stake are the lives of some 2 million people in Gaza and the reconstruction of the...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/5af3d546-fca1-416b-8a9b-627019d96779_60174b18.jpg?itok=XzCIA99y&v=1786903932', '2026-08-16T18:14:26+00:00', '2026-08-16T22:07:41.735376'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
